import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.Crpw6aS5.js";const o="data:image/svg+xml,%3csvg%20width='40'%20height='40'%20viewBox='0%200%2040%2040'%20fill='none'%20xmlns='http://www.w3.org/2000/svg'%3e%3cg%20clip-path='url(%23clip0_219_1775)'%3e%3cpath%20d='M39.054%2039.054H0V0H39.054V39.054ZM3.60889%2035.4475H35.4475V3.60654H3.60654V35.4451L3.60889%2035.4475Z'%20fill='%23FF8862'/%3e%3cpath%20fill-rule='evenodd'%20clip-rule='evenodd'%20d='M25.9061%2015.2485C25.9061%2014.0315%2024.9169%2013.0423%2023.6998%2013.0423C23.6883%2013.0423%2023.6768%2013.0424%2023.6653%2013.0426V12.9318H18.3655C19.2611%2010.8742%2021.3124%209.43576%2023.6998%209.43576C26.9117%209.43576%2029.515%2012.0391%2029.515%2015.2509C29.515%2018.4627%2026.9117%2021.066%2023.6998%2021.066C21.3191%2021.066%2019.2727%2019.6356%2018.3731%2017.5873H23.6653V17.4545C23.6768%2017.4546%2023.6883%2017.4547%2023.6998%2017.4547C24.9169%2017.4547%2025.9061%2016.4656%2025.9061%2015.2485Z'%20fill='%23FF8862'/%3e%3cpath%20d='M23.8577%209.43956L9.69946%209.4791L9.70953%2013.0856L23.8678%2013.0461L23.8577%209.43956Z'%20fill='%23FF8862'/%3e%3cpath%20d='M16.7029%2021.0989L16.6982%2017.49L23.7281%2017.4524L23.7328%2021.0589L16.7029%2021.0989Z'%20fill='%23FF8862'/%3e%3cpath%20d='M13.3054%2018.1432L20.8051%2025.6429H13.3054V18.1432ZM9.69885%209.43341V29.2494H29.5149L9.69885%209.43341Z'%20fill='%23FF8862'/%3e%3c/g%3e%3cdefs%3e%3cclipPath%20id='clip0_219_1775'%3e%3crect%20width='39.054'%20height='39.054'%20rx='0.258636'%20fill='white'/%3e%3c/clipPath%3e%3c/defs%3e%3c/svg%3e",n="data:image/png;base64,",l="/assets/graph.CCOVxdDJ.png",s="data:image/png;base64,",c="/assets/social-card.YtVu5J0J.png",v=JSON.parse('{"title":"Rivet — Open-Source Visual AI Programming Environment","description":"Imported note from rivet.ironcladapp.com","frontmatter":{"title":"Rivet — Open-Source Visual AI Programming Environment","description":"Imported note from rivet.ironcladapp.com"},"headers":[],"relativePath":"misc/artificial-intelligence/rivet-ironcladapp-com-rivet.md","filePath":"misc/artificial-intelligence/rivet-ironcladapp-com-rivet.md"}'),d={name:"misc/artificial-intelligence/rivet-ironcladapp-com-rivet.md"};function p(h,e,g,u,A,m){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="rivet-—-open-source-visual-ai-programming-environment" tabindex="-1">Rivet — Open-Source Visual AI Programming Environment <a class="header-anchor" href="#rivet-—-open-source-visual-ai-programming-environment" aria-label="Permalink to &quot;Rivet — Open-Source Visual AI Programming Environment&quot;">​</a></h1><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><ul><li>Type: webpage</li><li>Origin: <a href="https://rivet.ironcladapp.com/" target="_blank" rel="noreferrer">https://rivet.ironcladapp.com/</a></li><li>Imported: 2026-08-28</li><li>Images: 5 saved under <code>./assets/rivet-ironcladapp-com/</code> (graph, logos, social card)</li></ul><h2 id="content" tabindex="-1">Content <a class="header-anchor" href="#content" aria-label="Permalink to &quot;Content&quot;">​</a></h2><p><img src="'+o+'" alt="Rivet logo"></p><p><strong>The Open-Source Visual AI Programming Environment</strong></p><ul><li><a href="https://github.com/Ironclad/rivet/releases/latest" target="_blank" rel="noreferrer">Download latest release</a></li><li><a href="https://rivet.ironcladapp.com/docs" target="_blank" rel="noreferrer">Documentation</a></li><li><a href="https://github.com/Ironclad/rivet" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://discord.gg/qT8B2gv9Mg" target="_blank" rel="noreferrer">Discord</a> · <a href="https://www.youtube.com/@rivet_ts" target="_blank" rel="noreferrer">YouTube</a></li></ul><p>Built and used by:</p><p><img src="'+n+'" alt="Ironclad"></p><p><img src="'+l+'" alt="Rivet graph editor — visual prompt graph"></p><h3 id="what-is-rivet" tabindex="-1">What is Rivet? <a class="header-anchor" href="#what-is-rivet" aria-label="Permalink to &quot;What is Rivet?&quot;">​</a></h3><p>Rivet is a visual programming environment for building AI agents with LLMs. Iterate on your prompt graphs in Rivet, then run them directly in your application. With Rivet, teams can effectively design, debug, and collaborate on complex LLM prompt graphs, and deploy them in their own environment.</p><p>At Ironclad, we struggled to build AI agents programmatically. Rivet&#39;s visual environment, easy debugger, and remote executor unlocked our team&#39;s ability to collaborate on increasingly complex and powerful LLM prompt graphs.</p><p><img src="'+s+'" alt="Ironclad"> is the leading digital contracting platform. <a href="https://ironcladapp.com/product/ai-based-contract-management/" target="_blank" rel="noreferrer">Ironclad AI</a> helps legal teams with everything from reviewing contracts faster to answering questions about their obligations. Learn more at <a href="https://www.ironcladapp.com/" target="_blank" rel="noreferrer">ironcladapp.com</a>.</p><p>Rivet is built and used by Ironclad Research.</p><h3 id="why-rivet" tabindex="-1">Why Rivet? <a class="header-anchor" href="#why-rivet" aria-label="Permalink to &quot;Why Rivet?&quot;">​</a></h3><h4 id="visualize-and-build" tabindex="-1">Visualize and Build <a class="header-anchor" href="#visualize-and-build" aria-label="Permalink to &quot;Visualize and Build&quot;">​</a></h4><p>Visualize and build complex chains to create applications for production — not just prototyping.</p><h4 id="debug-remotely" tabindex="-1">Debug Remotely <a class="header-anchor" href="#debug-remotely" aria-label="Permalink to &quot;Debug Remotely&quot;">​</a></h4><p>See what&#39;s under the hood and observe the execution of prompt chains in your application, in real-time.</p><h4 id="collaborate" tabindex="-1">Collaborate <a class="header-anchor" href="#collaborate" aria-label="Permalink to &quot;Collaborate&quot;">​</a></h4><p>Rivet graphs are just YAML files, so you can version them in your team&#39;s repository, and review them using your favorite code review tools.</p><h3 id="see-it-in-action" tabindex="-1">See it in Action <a class="header-anchor" href="#see-it-in-action" aria-label="Permalink to &quot;See it in Action&quot;">​</a></h3><p>Demo video: <a href="https://www.youtube.com/watch?v=HhgM9MiShwA" target="_blank" rel="noreferrer">Rivet Demo on YouTube</a></p><h3 id="what-the-community-is-saying" tabindex="-1">What the Community is Saying <a class="header-anchor" href="#what-the-community-is-saying" aria-label="Permalink to &quot;What the Community is Saying&quot;">​</a></h3><blockquote><p>Rivet&#39;s visual programming environment is a game-changer. The visual nature of the tool, paired with how collaborative it is, allows us to create complex chains for AI agents in drastically less time than it would take in other environments. It&#39;s the best tool out there.</p><p>— <strong>Todd Berman</strong>, CTO, <a href="https://www.attentive.com/" target="_blank" rel="noreferrer">Attentive</a></p></blockquote><blockquote><p>Rivet really addressed some limitations that we were hitting up against... and some we didn&#39;t know we had. The visualization makes a big difference when working through agentic logic and really makes it easy to see what the AI is doing. But the ability to debug and collaborate across the team made a huge difference as well — we&#39;ve used it to launch our virtual mortgage servicing agent and are excited to see how the tool continues to evolve.</p><p>— <strong>Teddy Coleman</strong>, CTO, <a href="https://www.willowservicing.com/" target="_blank" rel="noreferrer">Willow Servicing</a></p></blockquote><blockquote><p>In order to build great product experiences we have to be able to iterate quickly. Leveraging tools like Rivet allows us to more accurately understand the tradeoffs between things like speed and quality as we build AI-powered experiences in Bento.</p><p>— <strong>Emily Wang</strong>, CEO, <a href="https://www.trybento.co/products/bentoai" target="_blank" rel="noreferrer">Bento</a></p></blockquote><blockquote><p>Rivet is an amazing tool for rapidly prototyping and visually understanding complex AI workflows. It&#39;s been wonderful collaborating with Ironclad to integrate AssemblyAI&#39;s audio transcription and understanding models into the Rivet ecosystem. We&#39;re excited to see what developers create equipped with such a powerful and capable toolkit!</p><p>— <strong>Domenic Donato</strong>, VP of Technology, <a href="https://www.assemblyai.com/" target="_blank" rel="noreferrer">AssemblyAI</a></p></blockquote><blockquote><p>Rivet is a super slick and compelling tool for prompt construction and LLM composition, particularly when you&#39;re trying to combine AI with many existing tools and APIs. I can see this becoming a popular tool for those working on robust and reliable AI applications.</p><p>— <strong>Beyang Liu</strong>, CTO, <a href="https://www.sourcegraph.com/" target="_blank" rel="noreferrer">Sourcegraph</a></p></blockquote><h3 id="ironclad-contract-ai" tabindex="-1">Ironclad Contract AI <a class="header-anchor" href="#ironclad-contract-ai" aria-label="Permalink to &quot;Ironclad Contract AI&quot;">​</a></h3><p>Ironclad Contract AI (CAI) is a virtual contract assistant, powered by AI agents, and developed with Rivet. CAI is capable of answering diverse questions about every stage of the contract lifecycle, directly using Ironclad&#39;s existing capabilities, like contract search, workflow process, and data visualization.</p><p><a href="https://ironcladapp.com/product/ironclad-contract-ai/" target="_blank" rel="noreferrer">Learn more about CAI</a></p><h3 id="get-started" tabindex="-1">Get Started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get Started&quot;">​</a></h3><p>Start building AI agents with Rivet in just a few simple steps:</p><ol><li>Follow the <a href="https://rivet.ironcladapp.com/docs/getting-started/installation" target="_blank" rel="noreferrer">Getting Started</a> guide to learn how to build AI agent graphs in Rivet.</li><li><a href="https://rivet.ironcladapp.com/docs/api-reference/getting-started-integration" target="_blank" rel="noreferrer">Integrate Rivet</a> into your Node or TypeScript application.</li><li>Experiment with the <a href="https://github.com/Ironclad/rivet-example" target="_blank" rel="noreferrer">Rivet example application</a> to get a sense for what developing and debugging a chat application looks like in Rivet.</li></ol><h3 id="figures" tabindex="-1">Figures <a class="header-anchor" href="#figures" aria-label="Permalink to &quot;Figures&quot;">​</a></h3><p><img src="'+c+'" alt="Rivet social preview card"></p><h2 id="key-takeaways" tabindex="-1">Key Takeaways <a class="header-anchor" href="#key-takeaways" aria-label="Permalink to &quot;Key Takeaways&quot;">​</a></h2><ul><li>Rivet is an open-source, node-based visual environment for designing, debugging, and deploying LLM prompt graphs in production apps.</li><li>Graphs serialize to YAML for version control and code review; a remote executor supports real-time debugging in running applications.</li><li>Ironclad uses Rivet internally for Contract AI (CAI) and maintains the project alongside docs, Discord, and a TypeScript/Node integration path.</li></ul>',40)])])}const b=a(d,[["render",p]]);export{v as __pageData,b as default};
